self.onInit = function () {
    var ADMIN_DASHBOARD_TITLE = 'admin felület';
    var ADMIN_STATE = 'gepek_attekintese';
    var MAP_WIDGET_TITLE = '';                      // '' = first map widget found in that state
    var ADMIN_PREFIX = 'Admin - ';
    var TPL = {
        small: 'Kis kontener minta',                // 1-2 machines
        large: 'Nagy Kontener Minta',               // 3-5 machines
        adminSmall: 'Admin - Kis kontener minta',
        adminLarge: 'Admin - Nagy Kontener Minta'
    };

    var root = self.ctx.$container[0];
    var $ = function (sel) { return root.querySelector(sel); };
    var http = self.ctx.http;
    var btn = $('.cf-save');
    var msg = $('.cf-msg');
    var noop = function () {};

    function show(text, ok) {
        msg.textContent = text;
        msg.className = 'cf-msg ' + (ok ? 'cf-ok' : 'cf-err');
    }

    function errText(e) {
        if (!e) { return 'Ismeretlen hiba'; }
        var m = (e.error && e.error.message) ? e.error.message : '';
        return (e.status ? e.status + ' ' : '') + (e.url ? '[' + e.url + '] ' : '') + (m || 'Ismeretlen hiba');
    }

    function num(v) {
        var n = parseFloat(String(v).replace(',', '.'));
        return isNaN(n) ? null : n;
    }

    function val(sel) { return $(sel).value.trim(); }

    function clearForm() {
        ['.cf-name', '.cf-machines', '.cf-country', '.cf-state', '.cf-city', '.cf-zip', '.cf-address',
         '.cf-lat', '.cf-lng'
        ].forEach(function (s) { $(s).value = ''; });
    }

    function uuid() {
        if (window.crypto && window.crypto.randomUUID) { return window.crypto.randomUUID(); }
        return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
            var r = Math.random() * 16 | 0;
            return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
        });
    }

    function runSteps(steps, done) {
        var i = 0;
        (function next() {
            if (i >= steps.length) { done(); return; }
            steps[i++](next);
        })();
    }

    // ---------- dashboards ----------

    function findDashboard(title, cb) {
        var url = '/api/tenant/dashboards?pageSize=100&page=0&textSearch=' + encodeURIComponent(title);
        http.get(url).subscribe(
            function (res) {
                var f = (res.data || []).filter(function (d) {
                    return String(d.title).toLowerCase() === title.toLowerCase();
                })[0];
                cb(f ? null : 'nem található a(z) "' + title + '" dashboard', f);
            },
            function (e) { cb(errText(e)); }
        );
    }

    // the entity is normally created with the customer as owner; if not, change the owner now
    function ensureOwner(type, entity, cid, cb) {
        if (entity.customerId && entity.customerId.id === cid) { cb(null); return; }
        http.post('/api/owner/CUSTOMER/' + cid + '/' + type + '/' + entity.id.id, []).subscribe(
            function () { cb(null); },
            function (e) {
                if (e && e.status === 200) { cb(null); return; }   // empty answer is not an error
                cb(errText(e));
            }
        );
    }

    // aliases "Gép #N" -> device whose name starts with "<customer> #N"
    function setAliases(cfg, customerName) {
        var count = 0;
        var aliases = cfg.entityAliases || {};
        Object.keys(aliases).forEach(function (id) {
            var a = aliases[id];
            
            if (/^fogyaszt[aá]s$/i.test(String(a.alias || '').trim())) {
                a.filter = {
                    type: 'entityName',
                    resolveMultiple: false,
                    entityType: 'ASSET',
                    entityNameFilter: customerName + ' fogyasztás'
                };
                return;
            }
            
            var m = /^g[ée]p\s*#\s*(\d+)$/i.exec(String(a.alias || '').trim());
            if (m) {
                a.filter = {
                    type: 'entityName',
                    resolveMultiple: false,
                    entityType: 'DEVICE',
                    entityNameFilter: customerName + ' #' + m[1]
                };
                count++;
            }
        });
        return count;
    }

    // copy of a template dashboard; ownerCid = null keeps it owned by the tenant
    function copyDashboard(templateTitle, newTitle, ownerCid, customerName, cb) {
        findDashboard(templateTitle, function (err, info) {
            if (err) { cb(err); return; }
            http.get('/api/dashboard/' + info.id.id).subscribe(
                function (tpl) {
                    var cfg = JSON.parse(JSON.stringify(tpl.configuration || {}));
                    var aliasCount = setAliases(cfg, customerName);
                    var body = { title: newTitle, configuration: cfg };
                    if (tpl.image) { body.image = tpl.image; }
                    if (ownerCid) { body.customerId = { id: ownerCid, entityType: 'CUSTOMER' }; }

                    http.post('/api/dashboard', body).subscribe(
                        function (saved) {
                            if (!ownerCid) { cb(null, saved, aliasCount); return; }
                            ensureOwner('DASHBOARD', saved, ownerCid, function (oerr) {
                                if (oerr) {
                                    http.delete('/api/dashboard/' + saved.id.id).subscribe(noop, noop);
                                    cb('a tulajdonos beállítása nem sikerült: ' + oerr);
                                    return;
                                }
                                cb(null, saved, aliasCount);
                            });
                        },
                        function (e) { cb('a dashboard létrehozása nem sikerült: ' + errText(e)); }
                    );
                },
                function (e) { cb(errText(e)); }
            );
        });
    }

    // ---------- admin overview: alias + marker on the map ----------

    function findState(cfg) {
        var states = cfg.states || {};
        if (states[ADMIN_STATE]) { return states[ADMIN_STATE]; }
        var key = Object.keys(states).filter(function (k) {
            return String(states[k].name || '').toLowerCase() === ADMIN_STATE.toLowerCase();
        })[0];
        return key ? states[key] : null;
    }

    function findMapWidget(cfg) {
        var state = findState(cfg);
        if (!state) { return { error: 'nem található a(z) "' + ADMIN_STATE + '" állapot' }; }
        var widgets = cfg.widgets || {};
        var found = null;
        Object.keys(state.layouts || {}).forEach(function (layout) {
            var ws = (state.layouts[layout] && state.layouts[layout].widgets) || {};
            Object.keys(ws).forEach(function (id) {
                var w = widgets[id];
                if (!found && w && /map/i.test(w.typeFullFqn || '') &&
                    (!MAP_WIDGET_TITLE || ((w.config || {}).title === MAP_WIDGET_TITLE))) {
                    found = w;
                }
            });
        });
        return found ? { widget: found }
                     : { error: 'nem található térkép widget a(z) "' + ADMIN_STATE + '" állapotban' };
    }

    function findMarkers(obj, depth) {
        if (!obj || typeof obj !== 'object' || depth > 6) { return null; }
        if (Array.isArray(obj.markers) && obj.markers.length) { return obj.markers; }
        var keys = Object.keys(obj);
        for (var i = 0; i < keys.length; i++) {
            var r = findMarkers(obj[keys[i]], depth + 1);
            if (r) { return r; }
        }
        return null;
    }

    function updateAdminDashboard(cid, customerName, cb) {
        findDashboard(ADMIN_DASHBOARD_TITLE, function (err, info) {
            if (err) { cb(err); return; }
            http.get('/api/dashboard/' + info.id.id).subscribe(
                function (dash) {
                    var cfg = dash.configuration || {};
                    cfg.entityAliases = cfg.entityAliases || {};

                    var r = findMapWidget(cfg);
                    if (r.error) { cb(r.error); return; }
                    var mapWidget = r.widget;

                    var aliasId = uuid();
                    var added = false;
                    var layers = findMarkers(mapWidget.config && mapWidget.config.settings, 0);
                    var dsList = mapWidget.config && mapWidget.config.datasources;

                    if (layers) {
                        var tpl = layers[layers.length - 1];
                        for (var i = layers.length - 1; i >= 0; i--) {
                            if (layers[i].dsEntityAliasId) { tpl = layers[i]; break; }
                        }
                        var layer = JSON.parse(JSON.stringify(tpl));
                        layer.dsType = 'entity';
                        layer.dsEntityAliasId = aliasId;
                        layers.push(layer);
                        added = true;
                    } else if (Array.isArray(dsList) && dsList.length) {
                        var ds = JSON.parse(JSON.stringify(dsList[dsList.length - 1]));
                        ds.type = 'entity';
                        ds.entityAliasId = aliasId;
                        dsList.push(ds);
                        added = true;
                    }
                    if (!added) { cb('a térkép widgetben nincs sablon marker'); return; }

                    var names = Object.keys(cfg.entityAliases).map(function (k) { return cfg.entityAliases[k].alias; });
                    var aliasName = customerName, n = 2;
                    while (names.indexOf(aliasName) >= 0) { aliasName = customerName + ' (' + (n++) + ')'; }

                    cfg.entityAliases[aliasId] = {
                        id: aliasId,
                        alias: aliasName,
                        filter: {
                            type: 'singleEntity',
                            resolveMultiple: false,
                            singleEntity: { entityType: 'CUSTOMER', id: cid }
                        }
                    };
                    dash.configuration = cfg;

                    http.post('/api/dashboard', dash).subscribe(
                        function () { cb(null); },
                        function (e) { cb(errText(e)); }
                    );
                },
                function (e) { cb(errText(e)); }
            );
        });
    }

    // ---------- rollback (the customer is deleted again if the attribute step fails) ----------

    function rollback(cid, text) {
        http.delete('/api/customer/' + cid).subscribe(
            function () { show(text + ' (az ügyfél nem jött létre)', false); btn.disabled = false; },
            function () { show(text + ' (az ügyfelet kézzel törölni kell)', false); btn.disabled = false; }
        );
    }
    
    // asset that holds the usage of the customer (attribute used_l)
    function createUsageAsset(cid, customerName, cb) {
        var body = { name: customerName + ' fogyasztás', type: 'default', customerId: { id: cid, entityType: 'CUSTOMER' } };
        http.post('/api/asset', body).subscribe(
            function (asset) {
                ensureOwner('ASSET', asset, cid, function (oerr) {
                    if (oerr) {
                        http.delete('/api/asset/' + asset.id.id).subscribe(noop, noop);
                        cb('tulajdonos: ' + oerr);
                        return;
                    }
                    http.post('/api/plugins/telemetry/ASSET/' + asset.id.id + '/attributes/SERVER_SCOPE', { used_l: 0 }).subscribe(
                        function () { cb(null); },
                        function (e) { cb(errText(e)); }
                    );
                });
            },
            function (e) { cb(errText(e)); }
        );
    }

    // ---------- main ----------

    btn.addEventListener('click', function () {
        var name = val('.cf-name');
        var machines = parseInt(val('.cf-machines'), 10);
        var lat = num($('.cf-lat').value);
        var lng = num($('.cf-lng').value);

        if (!name) { show('Add meg az ügyfél nevét.', false); return; }
        if (!(machines >= 1 && machines <= 5)) { show('Válaszd ki a gépek számát.', false); return; }
        if (lat === null || lat < -90 || lat > 90) { show('A szélesség érvénytelen (-90 és 90 között).', false); return; }
        if (lng === null || lng < -180 || lng > 180) { show('A hosszúság érvénytelen (-180 és 180 között).', false); return; }

        var small = machines <= 2;
        var customerBody = {
            title: name,
            country: val('.cf-country'),
            state: val('.cf-state'),
            city: val('.cf-city'),
            zip: val('.cf-zip'),
            address: val('.cf-address')
        };

        btn.disabled = true;
        show('Létrehozás...', true);

        // 1) customer
        http.post('/api/customer', customerBody).subscribe(
            function (customer) {
                var cid = customer.id.id;

                // 2) attributes
                http.post('/api/plugins/telemetry/CUSTOMER/' + cid + '/attributes/SERVER_SCOPE',
                          { latitude: lat, longitude: lng, machineCount: machines }).subscribe(
                    function () {
                        var warnings = [];
                        var ids = {};
                        show('Dashboardok létrehozása...', true);

                        runSteps([
                            // 3) customer dashboard
                            function (next) {
                                copyDashboard(small ? TPL.small : TPL.large, name, cid, name, function (err, d, n) {
                                    if (err) { warnings.push('ügyfél dashboard: ' + err); }
                                    else {
                                        ids.dashboardId = d.id.id;
                                        if (!n) { warnings.push('az ügyfél dashboardon nincs "Gép #N" alias'); }
                                    }
                                    next();
                                });
                            },
                            
                            // 3b) usage asset
                            function (next) {
                                createUsageAsset(cid, name, function (err) {
                                    if (err) { warnings.push('fogyasztás eszköz: ' + err); }
                                    next();
                                });
                            },
                            
                            // 4) admin dashboard (stays owned by the tenant)
                            function (next) {
                                copyDashboard(small ? TPL.adminSmall : TPL.adminLarge, ADMIN_PREFIX + name, null, name, function (err, d, n) {
                                    if (err) { warnings.push('admin dashboard: ' + err); }
                                    else {
                                        ids.adminDashboardId = d.id.id;
                                        if (!n) { warnings.push('az admin dashboardon nincs "Gép #N" alias'); }
                                    }
                                    next();
                                });
                            },
                            // 5) dashboard ids on the customer
                            function (next) {
                                if (!ids.dashboardId && !ids.adminDashboardId) { next(); return; }
                                http.post('/api/plugins/telemetry/CUSTOMER/' + cid + '/attributes/SERVER_SCOPE', ids).subscribe(
                                    function () { next(); },
                                    function (e) { warnings.push('dashboard azonosítók: ' + errText(e)); next(); }
                                );
                            },
                            // 6) alias + marker on the admin overview map
                            function (next) {
                                updateAdminDashboard(cid, name, function (err) {
                                    if (err) { warnings.push('admin térkép: ' + err); }
                                    next();
                                });
                            }
                        ], function () {
                            if (warnings.length) {
                                show('Az ügyfél létrejött, de: ' + warnings.join(' | '), false);
                            } else {
                                show('Kész: ügyfél, dashboardok és térkép marker létrejött. Felhasználót az "Új felhasználó" widgettel adhatsz hozzá.', true);
                            }
                            clearForm();
                            btn.disabled = false;
                        });
                    },
                    function (e) { rollback(cid, 'Attribútum hiba: ' + errText(e)); }
                );
            },
            function (e) {
                show('Ügyfél hiba: ' + errText(e), false);
                btn.disabled = false;
            }
        );
    });
};

self.onDestroy = function () {};

